python3 << 'PYTHON_EOF'
import json
import subprocess

# Complex nested test
test_input = {
  "pipeline": {"steps": [
    {"op": "branch", "branches": [
      {
        "when": "type == 'A'",
        "id": "branch_a",
        "steps": [
          {"op": "select", "columns": ["id", "value"]},
          {"op": "map", "as": "squared", "expr": "value * value"},
          {"op": "rename", "mapping": {"value": "original_value"}}
        ]
      },
      {
        "when": "otherwise",
        "id": "branch_b",
        "steps": [
          {"op": "limit", "n": 5}
        ]
      }
    ], "merge": {"strategy": "concat"}}
  ]},
  "dataset": [
    {"id": 1, "type": "A", "value": 10},
    {"id": 2, "type": "B", "value": 20},
    {"id": 3, "type": "A", "value": 30}
  ]
}

result = subprocess.run(
    ['python', 'etl_pipeline.py', '--execute'],
    input=json.dumps(test_input),
    capture_output=True,
    text=True
)

output = json.loads(result.stdout.strip())
print("Status:", output['status'])
if output['status'] == 'ok':
    print("Result:", json.dumps(output['data'], indent=2))
else:
    print("Error:", json.dumps(output, indent=2))
PYTHON_EOF
